import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def power(base, exp, mod):
    return pow(base, exp, mod)

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

# phi(10000) = 4000
phi = 4000
factors = prime_factorization(phi)

P = 0
for p in factors:
    exponent = factors[p]
    # Check divisors of phi, starting from phi/p
    temp_phi = phi
    while temp_phi >= 1:
        if phi % temp_phi == 0:
            # Check if 3^temp_phi == 1 mod 10000
            if power(3, temp_phi, 10000) == 1:
                P = temp_phi
                break
        temp_phi //= 2 # Just an arbitrary path to search smaller divisors
    if P > 0:
        break

# A safer approach is to iterate through all divisors of phi=4000
divisors = []
def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

all_divisors = get_divisors(4000)
P = 0
for d in all_divisors:
    if power(3, d, 10000) == 1:
        P = d
        break

print(f"The order of 3 modulo 10000 is: {P}")

